3219	// 多项弹性预约的联合排程与原子创建（schedule-flex）
3220	//
3221	// 读取本地 JSON 清单（{"items": [...]}，非空、有顺序），每项给出营业地时间窗口、
3222	// 所需连续分钟数与有顺序的需求组（每组列出一个可任选其一的候选资源数组）。
3223	// 为整份清单寻找同时可行的安排：每项完整落在自身窗口内，每组恰选一个候选，
3224	// 一项所选资源互不相同并全程固定（不换资源、不拼接间断）；新项之间仅共同资源
3225	// 的左闭右开时间重叠才冲突，端点相接可行。多个完整方案按清单顺序逐项比较：
3226	// 先比该项开始分钟，再按需求组顺序以字符串字典序比资源标识，第一处差异取
3227	// 较小者，随后才比较下一项（清单顺序只用于取舍，不限定活动发生先后）。
3228	// 有解时按清单顺序各创建一项普通预约（稳定、不复用标识，不加入系列、不改动
3229	// 既有预约与候补、不自动处理候补），原子保存全部预约后才报告成功；无整体解
3230	// 明确提示并退出 1，不保存部分方案。每次提交都是新的创建请求，不按清单路径
3231	// 或内容去重。
3232	//
3233	// 求解不逐项贪选最早：项 i 的开始分钟若被项 j 的占用“顶住”，则 s_i = s_j + d_j，
3234	// 故候选开始分钟取“基础空闲段起点”与“其他项占用结束（s_j + d_j）”的闭包
3235	// （仅候选资源集合有交集的项之间传播；按开始分钟归纳，最小方案的每个开始都
3236	// 落在该闭包内）。随后按清单顺序深度优先逐项试探：开始分钟升序、同一开始的
3237	// 资源序列按字典序升序枚举，首个完整方案即按上述比较的最小方案——不会因为
3238	// 逐项固定最早选择而漏掉须调整前项时间或资源的解，也不跳过受阻项。
3239	// ---------------------------------------------------------------------------
3240	
3241	interface FlexPlanItem {
3242	  index: number; // 1 基清单序号
3243	  startRaw: string; // 窗口开始（YYYY-MM-DDTHH:mm）
3244	  endRaw: string; // 窗口结束
3245	  startMin: number;
3246	  endMin: number;
3247	  duration: number; // 所需连续分钟数（正整数，不超过窗口长度）
3248	  groups: RequirementGroup[]; // 有顺序的需求组，每组恰选一个候选
3249	}
3250	
3251	interface FlexPlacement {
3252	  startMin: number;
3253	  endMin: number;
3254	  picks: string[]; // 按需求组顺序的所选资源
3255	}
3256	
3257	// 读取预约清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
3258	async function loadFlexManifest(file: string): Promise<unknown> {
3259	  let text: string;
3260	  try {
3261	    text = await readFile(file, 'utf8');
3262	  } catch (err) {
3263	    throw new BizError(`无法读取预约清单 ${file}: ${(err as Error).message}`);
3264	  }
3265	  try {
3266	    return JSON.parse(text);
3267	  } catch (err) {
3268	    throw new BizError(`预约清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
3269	  }
3270	}
3271	
3272	// 清单结构（与业务数据无关的纯类型校验）；返回逐项原始记录
3273	function parseFlexPlanShape(raw: unknown, file: string): Array<Record<string, unknown>> {
3274	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
3275	    throw new BizError(`预约清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
3276	  }
3277	  const o = raw as Record<string, unknown>;
3278	  for (const k of Object.keys(o)) {
3279	    if (k !== 'items') throw new BizError(`预约清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
3280	  }
3281	  if (!Array.isArray(o.items)) {
3282	    throw new BizError(`预约清单 ${file} 内容非法：items 必须是非空数组`);
3283	  }
3284	  const items = o.items as unknown[];
3285	  if (items.length === 0) throw new BizError(`预约清单 ${file} 为空：items 至少包含一项预约请求`);
3286	
3287	  const problems: string[] = [];
3288	  const records: Array<Record<string, unknown> | null> = [];
3289	  items.forEach((it, idx) => {
3290	    const at = `第 ${idx + 1} 项`;
3291	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
3292	      problems.push(`${at} 必须是对象`);
3293	      records.push(null);
3294	      return;
3295	    }
3296	    const rec = it as Record<string, unknown>;
3297	    for (const k of Object.keys(rec)) {
3298	      if (k !== 'window' && k !== 'duration' && k !== 'groups') {
3299	        problems.push(`${at} 存在未知字段 “${k}”（只允许 window、duration、groups）`);
3300	      }
3301	    }
3302	    if (typeof rec.window !== 'string' || rec.window === '') {
3303	      problems.push(`${at} 的 window 必须是 窗口开始/窗口结束 形式的非空字符串`);
3304	    }
3305	    if (typeof rec.duration !== 'number' || !Number.isInteger(rec.duration) || rec.duration <= 0) {
3306	      problems.push(`${at} 的 duration 必须是正整数分钟（不超过窗口长度）`);
3307	    }
3308	    if (!Array.isArray(rec.groups) || rec.groups.length === 0) {
3309	      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的需求组）`);
3310	    } else {
3311	      rec.groups.forEach((g, gi) => {
3312	        if (!Array.isArray(g) || g.length === 0) {
3313	          problems.push(`${at} 第 ${gi + 1} 需求组必须是非空数组（可任选其一的候选资源标识）`);
3314	        } else {
3315	          g.forEach((id) => {
3316	            if (typeof id !== 'string' || id === '') {
3317	              problems.push(`${at} 第 ${gi + 1} 需求组含非法候选：候选资源标识必须是非空字符串`);
3318	            }
3319	          });
3320	        }
3321	      });
3322	    }
3323	    records.push(rec);
3324	  });
3325	  if (problems.length > 0) {
3326	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3327	  }
3328	  return records as Array<Record<string, unknown>>;
3329	}
3330	
3331	// 逐项做与业务数据相关的校验（窗口真实有效、时长不超过窗口、组内重复与未知资源），
3332	// 收集全部问题后一次性拒绝整单；通过则返回排程项
3333	function parseFlexPlanItems(store: Store, records: Array<Record<string, unknown>>, file: string): FlexPlanItem[] {
3334	  const problems: string[] = [];
3335	  const items: Array<FlexPlanItem | null> = records.map((rec, idx) => {
3336	    const at = `第 ${idx + 1} 项`;
3337	    let ok = true;
3338	
3339	    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
3340	    try {
3341	      win = parseFlexWindow(rec.window as string, `${at}窗口`);
3342	    } catch (err) {
3343	      if (err instanceof BizError) {
3344	        problems.push(err.message);
3345	        ok = false;
3346	      } else {
3347	        throw err;
3348	      }
3349	    }
3350	
3351	    const duration = rec.duration as number; // 结构校验已保证正整数
3352	    if (win !== null && duration > win.endMin - win.startMin) {
3353	      problems.push(
3354	        `${at} 所需连续时长 ${duration} 分钟超过窗口长度 ${win.endMin - win.startMin} 分钟` +
3355	          `（窗口: ${win.start} → ${win.end}）`,
3356	      );
3357	      ok = false;
3358	    }
3359	
3360	    const groups: RequirementGroup[] = [];
3361	    (rec.groups as string[][]).forEach((ids, gi) => {
3362	      const glabel = `${at} 第 ${gi + 1} 需求组`;
3363	      const seen = new Set<string>();
3364	      const dupes: string[] = [];
3365	      for (const id of ids) {
3366	        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3367	        seen.add(id);
3368	      }
3369	      if (dupes.length > 0) {
3370	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3371	        ok = false;
3372	      }
3373	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3374	      if (unknown.length > 0) {
3375	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3376	        ok = false;
3377	      }
3378	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3379	    });
3380	
3381	    if (!ok || win === null) return null;
3382	    return {
3383	      index: idx + 1,
3384	      startRaw: win.start,
3385	      endRaw: win.end,
3386	      startMin: win.startMin,
3387	      endMin: win.endMin,
3388	      duration,
3389	      groups,
3390	    };
3391	  });
3392	  if (problems.length > 0) {
3393	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3394	  }
3395	  return items as FlexPlanItem[];
3396	}
3397	
3398	// 固定开始分钟上，按需求组顺序字典序升序枚举全部可行资源序列
3399	// （每组恰选一个候选，全部所选互不相同；候选已按标识排序）
3400	function* assignmentsInLexOrder(
3401	  groups: RequirementGroup[],
3402	  usable: (id: string) => boolean,
3403	): Generator<string[], void, undefined> {
3404	  const used = new Set<string>();
3405	  const acc: string[] = [];
3406	  function* rec(g: number): Generator<string[], void, undefined> {
3407	    if (g === groups.length) {
3408	      yield [...acc];
3409	      return;
3410	    }
3411	    for (const id of groups[g].candidates) {
3412	      if (used.has(id) || !usable(id)) continue;
3413	      used.add(id);
3414	      acc.push(id);
3415	      yield* rec(g + 1);
3416	      acc.pop();
3417	      used.delete(id);
3418	    }
3419	  }
3420	  yield* rec(0);
3421	}
3422	
3423	// 联合求解：找到即返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
3424	// 逐项（清单顺序）深度优先：开始分钟升序、同一开始的资源序列字典序升序，
3425	// 首个完整方案即“逐项先比开始分钟、再比资源序列”的最小方案。
3426	function solveFlexPlan(store: Store, items: FlexPlanItem[]): FlexPlacement[] | null {
3427	  // 每项各候选资源的基础空闲段：实际可用时间（开放合并后扣除有效停用并集）
3428	  // 裁进自身窗口，再扣除当前有效预约占用（已取消预约/停用与未兑现候补不阻挡）
3429	  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
3430	    const m = new Map<string, Array<[number, number]>>();
3431	    for (const g of it.groups) {
3432	      for (const id of g.candidates) {
3433	        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin));
3434	      }
3435	    }
3436	    return m;
3437	  });
3438	
3439	  // 候选开始分钟闭包：基础空闲段起点，加上“被其他项占用结束顶住”的起点
3440	  // s_i = s_j + d_j（仅候选资源集合有交集的项之间传播；值域有限，必收敛）
3441	  const candidateIds = items.map((it) => {
3442	    const set = new Set<string>();
3443	    for (const g of it.groups) for (const id of g.candidates) set.add(id);
3444	    return set;
3445	  });
3446	  const sharesCandidate = (a: number, b: number): boolean => {
3447	    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
3448	    return false;
3449	  };
3450	  const candStarts: Array<Set<number>> = items.map((it, i) => {
3451	    const set = new Set<number>();
3452	    for (const segs of baseFree[i].values()) {
3453	      for (const [s] of segs) {
3454	        if (s + it.duration <= it.endMin) set.add(s);
3455	      }
3456	    }
3457	    return set;
3458	  });
3459	  let changed = true;
3460	  while (changed) {
3461	    changed = false;
3462	    for (let j = 0; j < items.length; j++) {
3463	      for (let i = 0; i < items.length; i++) {
3464	        if (i === j || !sharesCandidate(i, j)) continue;
3465	        for (const s of candStarts[j]) {
3466	          const t = s + items[j].duration;
3467	          if (
3468	            t >= items[i].startMin &&
3469	            t + items[i].duration <= items[i].endMin &&
3470	            !candStarts[i].has(t)
3471	          ) {
3472	            candStarts[i].add(t);
3473	            changed = true;
3474	          }
3475	        }
3476	      }
3477	    }
3478	  }
3479	
3480	  // 已放置项对各资源的占用（随试探入栈/出栈增减）
3481	  const occById = new Map<string, Array<[number, number]>>();
3482	
3483	  const search = (idx: number): FlexPlacement[] | null => {
3484	    if (idx === items.length) return [];
3485	    const it = items[idx];
3486	    // 当前空闲段 = 基础空闲段扣除已放置项占用
3487	    const freeById = new Map<string, Array<[number, number]>>();
3488	    for (const [id, segs] of baseFree[idx]) {
3489	      const occ = occById.get(id);
3490	      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
3491	    }
3492	    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
3493	      const e = s + it.duration;
3494	      const cache = new Map<string, boolean>();
3495	      const usable = (id: string): boolean => {
3496	        let v = cache.get(id);
3497	        if (v === undefined) {
3498	          v = isFullyCovered(freeById.get(id)!, s, e);
3499	          cache.set(id, v);
3500	        }
3501	        return v;
3502	      };
3503	      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
3504	        for (const id of picks) {
3505	          const occ = occById.get(id) ?? [];
3506	          occ.push([s, e]);
3507	          occById.set(id, occ);
3508	        }
3509	        const rest = search(idx + 1);
3510	        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
3511	        for (const id of picks) occById.get(id)!.pop();
3512	      }
3513	    }
3514	    return null;
3515	  };
3516	
3517	  return search(0);
3518	}
3519	
3520	async function cmdScheduleFlex(args: string[]): Promise<void> {
3521	  const {values, positionals} = parseFlags(args, []);
3522	  if (values.size > 0) {
3523	    throw new UsageError(
3524	      `schedule-flex 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
3525	    );
3526	  }
3527	  if (positionals.length !== 1) {
3528	    throw new UsageError('用法: schedule-flex <预约清单文件>');
3529	  }
3530	  const manifestFile = positionals[0];
3531	
3532	  // 修改入口：先取得写入保护再读最新数据，排程至保存全程受保护
3533	  const file = activeDataFile;
3534	  const store = await loadStoreForWrite(file);
3535	  const records = parseFlexPlanShape(await loadFlexManifest(manifestFile), manifestFile);
3536	  const items = parseFlexPlanItems(store, records, manifestFile);
3537	
3538	  const plan = solveFlexPlan(store, items);
3539	  if (plan === null) {
3540	    throw new BizError(
3541	      `无整体解：清单 ${manifestFile} 的 ${items.length} 项预约不存在同时可行的安排` +
3542	        '（每项须完整落在自身窗口内，各组所选资源互不相同并全程固定，' +
3543	        '新项之间共同资源时间不得重叠）。未创建任何预约，数据文件未改动。',
3544	    );
3545	  }
3546	
